#include <stdio.h>
#include <string.h>
#include <thinkthen.h>

thinkthen_engine *tt = thinkthen_engine_new();

/* praise, a bug, and a double charge in one message */
const char *tag = "{\"tag\": \"Which labels fit this message?\", "
    "\"labels\": [\"praise\", \"bug\", \"billing\"], "
    "\"evidence\": \"Love the new dashboard, but export "
    "crashes the app, and I was charged twice.\"}";
char *labels = thinkthen_call(tt, tag);
puts(labels ? labels : thinkthen_error_message(tt));
thinkthen_free_string(labels);
